import csv
import glob
from collections import defaultdict

# CBSA names to analyze
target_areas = [
    "Portland-Vancouver-Hillsboro, OR-WA",
    "Wichita, KS",
    "San Diego-Carlsbad, CA"
]

# Threshold for "Good" AQI (<= 4.4 ppm)
threshold = 4.4

results = {}

for year in range(2000, 2011):
    filename = f"epa_data/daily_42101_{year}.csv"

    area_data = defaultdict(list)  # area -> list of (date, max_value)

    with open(filename, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            cbsa = row['CBSA Name']
            if cbsa in target_areas:
                date = row['Date Local']
                max_val = float(row['1st Max Value'])
                area_data[cbsa].append((date, max_val))

    # Check each area for the year
    year_results = {}
    for area in target_areas:
        if area not in area_data:
            year_results[area] = "No data"
            continue

        # Get all days and find max value per day
        daily_max = defaultdict(float)
        for date, val in area_data[area]:
            if val > daily_max[date]:
                daily_max[date] = val

        # Check if all days have max <= threshold
        all_good = all(v <= threshold for v in daily_max.values())

        # Also check if we have data for all 365/366 days
        num_days = len(daily_max)

        # Find max value for the year
        year_max = max(daily_max.values()) if daily_max else 0

        year_results[area] = {
            'num_days': num_days,
            'max_value': year_max,
            'all_good': all_good
        }

    results[year] = year_results
    print(f"Year {year}:")
    for area in target_areas:
        r = year_results[area]
        if isinstance(r, dict):
            print(f"  {area}: {r['num_days']} days, max={r['max_value']:.2f} ppm, all_good={r['all_good']}")
        else:
            print(f"  {area}: {r}")

# Find years where all three areas have all_good=True
good_years = []
for year in range(2000, 2011):
    all_areas_good = True
    for area in target_areas:
        r = results[year][area]
        if isinstance(r, dict):
            if not r['all_good']:
                all_areas_good = False
                break
        else:
            all_areas_good = False
            break
    if all_areas_good:
        good_years.append(year)

print(f"\nYears where all three areas had all days in Good range: {good_years}")

